import java.util.*;
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) {
        byte[] originalData = "HELLOWORLD".getBytes(StandardCharsets.UTF_8); // 10 bytes
        int numDataShards = 2; // splits into 2 data shards of 5 bytes each, plus 1 parity shard

        ErasureCoder coder = new ErasureCoder();
        byte[][] shards = coder.encode(originalData, numDataShards);

        System.out.println("Data shard 0: " + new String(shards[0], StandardCharsets.UTF_8));
        System.out.println("Data shard 1: " + new String(shards[1], StandardCharsets.UTF_8));
        System.out.println("Parity shard: " + bytesToHex(shards[2]));

        // Simulate losing data shard 1 (the disk holding "WORLD" fails).
        byte[] reconstructed = coder.reconstructMissingShard(shards, 1, numDataShards);
        System.out.println("Reconstructed shard 1: " + new String(reconstructed, StandardCharsets.UTF_8));
        System.out.println("Reconstruction exactly matches the original lost shard: " + Arrays.equals(reconstructed, shards[1]));
    }

    static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) sb.append(String.format("%02x", b));
        return sb.toString();
    }
}

// A simple, real XOR-based erasure code: splits an object into equal-sized
// data shards and computes one parity shard as the byte-wise XOR of all of
// them, tolerating the loss of exactly one shard, the same idea RAID 5 uses.
class ErasureCoder {
    // Encodes data into numDataShards data shards plus 1 parity shard.
    byte[][] encode(byte[] data, int numDataShards) {
        int shardSize = (data.length + numDataShards - 1) / numDataShards; // ceiling division, equal-sized shards
        byte[][] shards = new byte[numDataShards + 1][shardSize]; // last index is the parity shard

        for (int i = 0; i < numDataShards; i++) {
            int start = i * shardSize;
            for (int j = 0; j < shardSize; j++) {
                int sourceIndex = start + j;
                shards[i][j] = (sourceIndex < data.length) ? data[sourceIndex] : 0; // zero-pad if data doesn't evenly divide
            }
        }

        for (int j = 0; j < shardSize; j++) {
            byte parityByte = 0;
            for (int i = 0; i < numDataShards; i++) {
                parityByte ^= shards[i][j]; // parity is the XOR of every data shard's corresponding byte
            }
            shards[numDataShards][j] = parityByte;
        }

        return shards;
    }

    // Reconstructs a missing shard (data or parity) by XORing every other
    // remaining shard together; XOR's self-cancelling property means this
    // always recovers exactly the missing shard's original bytes.
    byte[] reconstructMissingShard(byte[][] shards, int missingIndex, int numDataShards) {
        int shardSize = shards[0].length;
        byte[] result = new byte[shardSize];
        for (int i = 0; i < shards.length; i++) {
            if (i == missingIndex) continue; // skip the shard we're reconstructing
