class ErasureCoder:
    # A simple, real XOR-based erasure code: splits an object into equal-sized
    # data shards and computes one parity shard as the byte-wise XOR of all
    # of them, tolerating the loss of exactly one shard, the same idea RAID 5 uses.
    def encode(self, data, num_data_shards):
        shard_size = (len(data) + num_data_shards - 1) // num_data_shards  # ceiling division, equal-sized shards
        shards = [bytearray(shard_size) for _ in range(num_data_shards + 1)]  # last index is the parity shard

        for i in range(num_data_shards):
            start = i * shard_size
            for j in range(shard_size):
                source_index = start + j
                shards[i][j] = data[source_index] if source_index < len(data) else 0  # zero-pad if needed

        for j in range(shard_size):
            parity_byte = 0
            for i in range(num_data_shards):
                parity_byte ^= shards[i][j]  # parity is the XOR of every data shard's corresponding byte
            shards[num_data_shards][j] = parity_byte

        return [bytes(s) for s in shards]

    def reconstruct_missing_shard(self, shards, missing_index, num_data_shards):
        shard_size = len(shards[0])
        result = bytearray(shard_size)
        for i, shard in enumerate(shards):
            if i == missing_index:
                continue  # skip the shard we're reconstructing
            for j in range(shard_size):
                result[j] ^= shard[j]
        return bytes(result)


def main():
    original_data = "HELLOWORLD".encode("utf-8")  # 10 bytes
    num_data_shards = 2  # splits into 2 data shards of 5 bytes each, plus 1 parity shard

    coder = ErasureCoder()
    shards = coder.encode(original_data, num_data_shards)

    print("Data shard 0:", shards[0].decode("utf-8"))
    print("Data shard 1:", shards[1].decode("utf-8"))
    print("Parity shard:", shards[2].hex())

    # Simulate losing data shard 1 (the disk holding "WORLD" fails).
    reconstructed = coder.reconstruct_missing_shard(shards, 1, num_data_shards)
    print("Reconstructed shard 1:", reconstructed.decode("utf-8"))
    print("Reconstruction exactly matches the original lost shard:", reconstructed == shards[1])


if __name__ == "__main__":
    main()

