// A simple, real XOR-based erasure code: splits an object into equal-sized
// data shards and computes one parity shard as the byte-wise XOR of all of
// them, tolerating the loss of exactly one shard, the same idea RAID 5 uses.
class ErasureCoder {
public:
    vector<vector<uint8_t>> encode(const vector<uint8_t>& data, int numDataShards) {
        int shardSize = (data.size() + numDataShards - 1) / numDataShards; // ceiling division, equal-sized shards
        vector<vector<uint8_t>> shards(numDataShards + 1, vector<uint8_t>(shardSize, 0)); // last index is the parity shard

        for (int i = 0; i < numDataShards; i++) {
            int start = i * shardSize;
            for (int j = 0; j < shardSize; j++) {
                int sourceIndex = start + j;
                shards[i][j] = (sourceIndex < (int)data.size()) ? data[sourceIndex] : 0; // zero-pad if needed
            }
        }

        for (int j = 0; j < shardSize; j++) {
            uint8_t parityByte = 0;
            for (int i = 0; i < numDataShards; i++) {
                parityByte ^= shards[i][j]; // parity is the XOR of every data shard's corresponding byte
            }
            shards[numDataShards][j] = parityByte;
        }

        return shards;
    }

    vector<uint8_t> reconstructMissingShard(const vector<vector<uint8_t>>& shards, int missingIndex) {
        int shardSize = shards[0].size();
        vector<uint8_t> result(shardSize, 0);
        for (size_t i = 0; i < shards.size(); i++) {
            if ((int)i == missingIndex) continue; // skip the shard we're reconstructing
            for (int j = 0; j < shardSize; j++) {
                result[j] ^= shards[i][j];
            }
        }
        return result;
    }
};

string bytesToString(const vector<uint8_t>& bytes) {
    return string(bytes.begin(), bytes.end());
}

string bytesToHex(const vector<uint8_t>& bytes) {
    stringstream ss;
    for (uint8_t b : bytes) ss << hex << setw(2) << setfill('0') << (int)b;
    return ss.str();
}

int main() {
    string originalStr = "HELLOWORLD"; // 10 bytes
    vector<uint8_t> originalData(originalStr.begin(), originalStr.end());
    int numDataShards = 2; // splits into 2 data shards of 5 bytes each, plus 1 parity shard

    ErasureCoder coder;
    vector<vector<uint8_t>> shards = coder.encode(originalData, numDataShards);

    cout << "Data shard 0: " << bytesToString(shards[0]) << endl;
    cout << "Data shard 1: " << bytesToString(shards[1]) << endl;
    cout << "Parity shard: " << bytesToHex(shards[2]) << endl;

    // Simulate losing data shard 1 (the disk holding "WORLD" fails).
    vector<uint8_t> reconstructed = coder.reconstructMissingShard(shards, 1);
    cout << "Reconstructed shard 1: " << bytesToString(reconstructed) << endl;
    cout << "Reconstruction exactly matches the original lost shard: " << (reconstructed == shards[1] ? "true" : "false") << endl;

    return 0;
}

